<script setup>
import { ref,computed,watch } from 'vue';
import { ALL_FOODS,PHOTO_FOODS,REFERENCE_FOODS,FOOD_BY_ID,rankFoods } from '../data/catalogue.js';
import { FOOD_CATEGORIES,CATEGORY_BY_ID } from '../data/foodCategories.js';
import { formatNutrient } from '../lib/foodNutrition.js';
import { aiRequest } from '../lib/aiClient.js';
import FoodCard from '../components/FoodCard.vue';
import AppIcon from '../components/AppIcon.vue';
import imageCredits from '../data/foodImageSources.json' with {type:'json'};
defineEmits(['detail']);
const query=ref(''),submitted=ref(''),category=ref(''),subcategory=ref(''),sort=ref('relevance'),page=ref(1),suggestionsOpen=ref(false);
const comparison=ref([]),compareMessage=ref(''),askOpen=ref(false),question=ref(''),asking=ref(false),answer=ref(null),askError=ref('');
// Photo cards use source-linked local photographs; nutrient samples remain available separately.
const browseFoods=PHOTO_FOODS;
const browseIds=new Set(PHOTO_FOODS.map(f=>f.key));
const referenceIds=new Set(REFERENCE_FOODS.map(f=>f.key));
const referenceMatches=computed(()=>submitted.value?rankFoods(submitted.value).map(x=>x.food).filter(f=>referenceIds.has(f.key)&&!browseIds.has(f.key)):[]);
function browseSearch(term,limit=ALL_FOODS.length){return rankFoods(term).map(x=>x.food).filter(food=>browseIds.has(food.key)).slice(0,limit);}
const suggestions=computed(()=>query.value.trim()?browseSearch(query.value,ALL_FOODS.length).slice(0,5):[]);
const countCategory=id=>browseFoods.filter(food=>food.category===id).length;
const localPhotoCount=PHOTO_FOODS.length;
const featured=[...new Map(['白菜','西兰花','西红柿','胡萝卜','苹果','香蕉','蓝莓','米饭','牛奶','鸡蛋','豆腐','鸡胸肉'].map(term=>{const choices=rankFoods(term).map(x=>x.food).filter(food=>browseIds.has(food.key));return choices.find(food=>food.source)||choices[0];}).filter(Boolean).map(food=>[food.key,food])).values()];
const available=computed(()=>{let foods=submitted.value?browseSearch(submitted.value):[...browseFoods].sort((a,b)=>Number(!a.source)-Number(!b.source));if(category.value)foods=foods.filter(food=>food.category===category.value);return foods;});
const subcategories=computed(()=>[...new Set(available.value.map(food=>food.subcategory))]);
const results=computed(()=>{let foods=available.value.filter(food=>!subcategory.value||food.subcategory===subcategory.value);if(sort.value!=='relevance'){const [key,direction]=sort.value.split(':');foods=[...foods].sort((a,b)=>{if(key==='name')return a.name.localeCompare(b.name,'zh');const x=a.nutrients[key],y=b.nutrients[key];if(x==null||y==null)return Number(x==null)-Number(y==null);return(direction==='asc'?1:-1)*(x-y);});}return foods;});
const pages=computed(()=>Math.max(1,Math.ceil(results.value.length/12)));const visible=computed(()=>results.value.slice((page.value-1)*12,page.value*12));
watch([subcategory,sort],()=>page.value=1);
function search(term=query.value){query.value=term.trim();submitted.value=query.value;category.value='';subcategory.value='';page.value=1;suggestionsOpen.value=false;}
function chooseCategory(id){category.value=id;submitted.value='';query.value='';subcategory.value='';page.value=1;sort.value='relevance';}
function reset(){category.value='';submitted.value='';query.value='';subcategory.value='';page.value=1;}
function compare(id){compareMessage.value='';if(comparison.value.includes(id))comparison.value=comparison.value.filter(key=>key!==id);else if(comparison.value.length<2)comparison.value.push(id);else compareMessage.value='每次选择两种食物进行比较。';}
async function ask(){if(asking.value||!question.value.trim())return;asking.value=true;askError.value='';answer.value=null;try{answer.value=await aiRequest('ask',{question:question.value.trim(),foodIds:comparison.value});}catch(error){askError.value=error.message;}finally{asking.value=false;}}
</script>
<template><div class="vb-food-hub"><div class="vb-page-title"><div><p class="vb-eyebrow">从认识食物开始</p><h1>食物浏览与查询</h1><p>{{ localPhotoCount.toLocaleString() }} 项有照片的食材与菜式，按名称搜索，打开卡片查看营养与来源。</p></div><button class="vb-button vb-button-quiet" :aria-expanded="askOpen" @click="askOpen=!askOpen"><AppIcon name="sparkles" :size="17" />问 AI</button></div>
 <section class="vb-glass vb-food-search-hero"><span class="vb-icon-badge"><AppIcon name="search" :size="23" /></span><div><h2>今天想了解哪一种食物？</h2><p>名称、别名都能查。营养数据统一按每 100 克可食部展示。</p></div><form class="vb-food-search-form" @submit.prevent="search()"><div class="vb-food-search-input"><AppIcon name="search" :size="19" /><input v-model="query" type="search" placeholder="试试香蕉、西红柿、鸡胸肉…" aria-label="食物查询关键词" autocomplete="off" @focus="suggestionsOpen=true" /><button v-if="query" type="button" class="vb-icon-button" aria-label="清空食物查询" @click="reset"><AppIcon name="close" :size="15" /></button><div v-if="suggestionsOpen&&suggestions.length" class="vb-food-suggestions"><button v-for="food in suggestions" :key="food.key" type="button" @click="search(food.name)">{{ food.name }}<small>{{ food.state }}</small></button></div></div><button class="vb-button vb-button-primary" type="submit">搜索</button></form><div class="vb-recommended"><span>推荐搜索</span><button v-for="word in ['香蕉','白菜','燕麦','鸡胸肉','鸡蛋']" :key="word" type="button" @click="search(word)">{{ word }}</button></div></section>
 <section v-if="askOpen" class="vb-glass vb-food-ask"><div class="vb-section-heading"><div><span class="vb-small-label">以数据库为依据</span><h2>问问 AI，读懂食物数据</h2></div><AppIcon name="sparkles" /></div><p class="vb-data-note">问题与相关数据库条目会发送给 DeepSeek。数值来自食物库，AI 负责解释。</p><div v-if="comparison.length" class="vb-comparison-chips"><button v-for="id in comparison" :key="id" type="button" @click="compare(id)">{{ FOOD_BY_ID[id].name }} ×</button></div><form @submit.prevent="ask"><label class="vb-field">你的问题<textarea v-model="question" maxlength="600" rows="2" placeholder="100 克香蕉大约有多少热量？或先选两种食物，问问蛋白质的区别。" /></label><div class="vb-ask-bottom"><button type="button" class="vb-text-button" @click="question=comparison.length===2?'这两种食物的蛋白质有什么区别？':'100 克香蕉大约有多少热量？'">填入示例问题</button><button type="submit" class="vb-button vb-button-primary" :disabled="asking||!question.trim()">{{ asking?'正在查询与分析…':'发送问题' }}</button></div></form><p v-if="askError" class="vb-feature-error" role="alert">{{ askError }}</p><div v-if="answer" class="vb-ai-answer"><h3>数据库数值</h3><p v-if="!answer.database.length" class="vb-data-note">没有匹配的数据库条目，暂无精确营养数值。</p><div class="vb-answer-foods"><button v-for="food in answer.database" :key="food.id" type="button" @click="$emit('detail',food.id)"><strong>{{ food.name }} →</strong><span>{{ food.grams }} 克可食部 · 热量 {{ formatNutrient(food.portion.energy) }}{{ food.portion.energy!=null?' kcal':'' }} · 蛋白质 {{ formatNutrient(food.portion.protein) }}{{ food.portion.protein!=null?' g':'' }}</span><small>{{ food.source?.name||'原有目录，暂无成分数据' }}</small></button></div><h3>AI 解释</h3><p>{{ answer.answer.summary }}</p><p>{{ answer.answer.explanation }}</p><p class="vb-data-note">{{ answer.answer.limitations }}</p><small class="vb-data-note">{{ answer.model }} · {{ new Date(answer.generatedAt).toLocaleString() }}</small></div></section>
 <div v-if="comparison.length" class="vb-compare-bar"><span>已选 {{ comparison.length }} 种食物</span><button v-for="id in comparison" :key="id" @click="compare(id)">{{ FOOD_BY_ID[id].name }} ×</button><button class="vb-text-button" @click="askOpen=true;question='这两种食物的蛋白质有什么区别？'">问 AI 比较 →</button></div><p v-if="compareMessage" class="vb-data-note" role="status">{{ compareMessage }}</p>
 <template v-if="!category&&!submitted"><div class="vb-section-heading"><div><h2>常见食物</h2><p>从你熟悉的食材开始。</p></div></div><div class="vb-food-results-grid"><FoodCard v-for="food in featured" :key="food.key" :food="food" :compared="comparison.includes(food.key)" @detail="$emit('detail',$event)" @compare="compare" /></div><div class="vb-section-heading vb-category-heading"><div><h2>按类别探索</h2><p>{{ browseFoods.length.toLocaleString() }} 项食材与菜式，每项都有直接展示的真实照片。</p></div></div><div class="vb-food-category-grid"><button v-for="item in FOOD_CATEGORIES.filter(item=>countCategory(item.id)>0)" :key="item.id" type="button" class="vb-food-category-card" @click="chooseCategory(item.id)"><img :src="item.image" :alt="item.name+'分类示意图'" loading="lazy" /><span><small>{{ countCategory(item.id).toLocaleString() }} 种食物</small><strong>{{ item.name }}</strong><em>{{ item.description }} <AppIcon name="arrow" :size="16" /></em></span></button></div><p class="vb-photo-library-note">照片已随网站保存。图片作者与许可可以在详情中查看；有可靠成分样本的食物显示营养值，其余保持未知。</p></template>
 <template v-else><div class="vb-food-results-top"><button type="button" class="vb-text-button" @click="reset"><AppIcon name="back" :size="15" />分类总览</button><h2>{{ category?CATEGORY_BY_ID[category].name:'“'+submitted+'”的食物照片与营养资料' }}</h2><span>{{ results.length.toLocaleString() }} 个结果 · 每 100 克可食部</span></div><div class="vb-food-filter"><div v-if="subcategories.length<=10"><button :class="{selected:!subcategory}" @click="subcategory=''">全部</button><button v-for="sub in subcategories" :key="sub" :class="{selected:subcategory===sub}" @click="subcategory=sub">{{ sub }}</button></div><label v-else>筛选<select v-model="subcategory" aria-label="食物类型筛选"><option value="">全部类型</option><option v-for="sub in subcategories" :key="sub" :value="sub">{{ sub }}</option></select></label><label>排序<select v-model="sort" aria-label="食物营养指标排序"><option value="relevance">默认顺序</option><option value="energy:asc">热量从低到高</option><option value="energy:desc">热量从高到低</option><option value="protein:desc">蛋白质从高到低</option><option value="fiber:desc">膳食纤维从高到低</option><option value="name:asc">名称</option></select></label></div><div class="vb-food-results-grid"><FoodCard v-for="food in visible" :key="food.key" :food="food" :compared="comparison.includes(food.key)" @detail="$emit('detail',$event)" @compare="compare" /></div><div v-if="!results.length" class="vb-glass vb-food-empty"><AppIcon name="search" :size="34" /><h2>没有找到匹配的食物</h2><p>试试常见中文名、英文原名或类别名称。</p><button class="vb-button vb-button-quiet" @click="reset">返回食物总览</button></div><nav v-if="pages>1" class="vb-food-pagination" aria-label="食物列表分页"><button :disabled="page===1" @click="page--">上一页</button><span>第 {{ page }} / {{ pages }} 页</span><button :disabled="page===pages" @click="page++">下一页</button></nav></template>
 <details v-if="submitted&&referenceMatches.length" class="vb-food-source-note vb-reference-samples"><summary>其他营养数据样本 · {{ referenceMatches.length.toLocaleString() }} 条</summary><p>细分品种、品牌和加工状态的原始成分样本仍保留。请按你实际食用的食物选择；这些数据样本可能没有单独配图。</p><div class="vb-reference-sample-list"><button v-for="food in referenceMatches.slice(0,80)" :key="food.key" type="button" @click="$emit('detail',food.key)"><strong>{{ food.name }}</strong><span>{{ food.source?.name||'食物记录目录' }} · 查看数据 →</span></button></div><p v-if="referenceMatches.length>80">当前显示前80条，请增加名称或加工状态关键词缩小范围。</p></details>
 <details class="vb-food-source-note"><summary>数据口径与图片署名</summary><p>营养数据来自 USDA SR28（2016 年 5 月修订，公有领域），展示的是对应品种、生熟和加工状态的数据库样本。原目录中没有准确对应的数据保持缺失，不能视为 0。旧记录需确认具体参考条目后参与营养计算。分类结构参考 HowToEat。食物卡片直接使用固定保存的真实照片，不在用户浏览时自动选择搜索引擎结果。照片与名称关联依据来自具体图片说明、百科食物条目或逐项绑定；作者、来源和许可保留在详情中。食材参考照片不证明营养样本具体品牌或品种；扩展样本保留完整英文描述，中文为食材类别提示；校园混合菜尚无配方时保持营养未知。</p><p>碳水采用差减法，含膳食纤维；维 A 为 μg RAE，叶酸为 μg DFE。配方、产地和做法会造成差异。婴幼儿食品类仅为成分查询，不提供婴幼儿膳食推荐。</p><p>每项食物照片的作者、原图链接和许可均在食物详情中显示。</p><p>分类总览图片：</p><ul><li v-for="credit in imageCredits" :key="credit.key">{{ CATEGORY_BY_ID[credit.key]?.name }}：<a :href="credit.sourceUrl" target="_blank" rel="noopener">{{ credit.title }}</a> · {{ credit.author }} · <a :href="credit.licenseUrl" target="_blank" rel="noopener">{{ credit.license }}</a> · {{ credit.modifications }}</li></ul></details>
 </div></template>

